                            last_message_from: "me" | "them" | null;
                            /** @description The newest message text Curviate holds for the chat. Null when it holds none. */
                            preview: {
                                /** @description The text. */
                                text?: string;
                                /** @description When it was sent. */
                                at?: string;
                            } | null;
