                            name: string;
                            /** @enum {string} */
                            status: "draft" | "scheduled" | "active" | "paused" | "completed" | "archived";
                            /**
                             * @description Why it is paused; null unless status is paused.
                             * @enum {string|null}
                             */
                            pause_reason: "user" | "acceptance_floor" | "no_sending_account" | "tier_required" | null;
