                range?: "7d" | "30d" | "90d" | "12m" | "all";
                /** @description Groups daily: day, week (from Monday), month, or auto (day to 90 days, week to 366, month beyond). Default: auto with range, day with from/to. */
                bucket?: "auto" | "day" | "week" | "month";
